#!/usr/bin/env python3
import gzip, base64
from pathlib import Path
from datetime import datetime, timezone
stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
js = gzip.decompress(base64.b64decode(''))
css = gzip.decompress(base64.b64decode(''))
jp = Path('/opt/liquidgov/assets/juketube.js')
cp = Path('/opt/liquidgov/assets/juketube.css')
jp.with_name(jp.name + '.bak-v12-' + stamp).write_bytes(jp.read_bytes() if jp.exists() else b'')
if cp.exists():
    cp.with_name(cp.name + '.bak-v12-' + stamp).write_bytes(cp.read_bytes())
jp.parent.mkdir(parents=True, exist_ok=True)
jp.write_bytes(js)
cp.write_bytes(css)
print('js', len(js), 'css', len(css))
srcp = Path('/opt/liquidgov/src/http_server.cpp')
s = srcp.read_text()
start = s.find('std::string global_jukebox_widget')
end = s.find('std::string jukebox_standalone_page')
print('widget_start', start, 'widget_end', end)
need = 0
NEW_FN = 'std::string global_jukebox_widget(const std::string& yt_key, const std::string& user) {\n    (void)yt_key; (void)user;\n    return "<link rel=\\"stylesheet\\" href=\\"/assets/juketube.css?v=12\\">"\n           "<div id=\\"juketube-root\\"></div>"\n           "<script src=\\"/assets/juketube.js?v=12\\" defer></script>";\n}\n\n'
if start < 0 or end <= start:
    print('STOP widget_fn')
else:
    cur = s[start:end]
    if '/assets/juketube.js?v=12' in cur:
        print('wrap_already_v12')
    else:
        srcp.with_name(srcp.name + '.bak-v12-' + stamp).write_text(s)
        s = s[:start] + NEW_FN + s[end:]
        srcp.write_text(s)
        need = 1
        print('wrap_patched', len(cur), '->', len(NEW_FN))
print('NEED_BUILD', need)
print('DONE')
